<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{SupportAccessGrant,SupportTicket}; use App\Services\AuditLogger; use App\Support\TenantContext; use Illuminate\Http\Request;
final class SupportController { public function tickets(){return response()->json(['data'=>SupportTicket::where('tenant_id',app(TenantContext::class)->id())->latest()->paginate(25)]);} public function createTicket(Request $r,AuditLogger $audit){$t=app(TenantContext::class)->id();$d=$r->validate(['subject'=>'required|string|max:200','description'=>'required|string','priority'=>'nullable|in:low,normal,high,urgent']);$ticket=SupportTicket::create([...$d,'tenant_id'=>$t,'created_by'=>$r->user()->id]);$audit->record($r,'support.ticket.created',$t,$ticket);return response()->json(['data'=>$ticket],201);} public function requestAccess(Request $r,SupportAccessGrant $grant,AuditLogger $audit){abort_unless($grant->tenant_id===app(TenantContext::class)->id(),404);abort_unless($grant->support_user_id===$r->user()->id,403);$grant->update(['state'=>'requested']);$audit->record($r,'support.access.requested',$grant->tenant_id,$grant);return response()->json(['data'=>$grant]);} public function grant(Request $r,AuditLogger $audit){$d=$r->validate(['tenant_id'=>'required|uuid','support_user_id'=>'required|uuid','reason'=>'required|string','starts_at'=>'required|date','expires_at'=>'required|date|after:starts_at']);$grant=SupportAccessGrant::create([...$d,'state'=>'requested']);$audit->record($r,'platform.support.access.created',$d['tenant_id'],$grant);return response()->json(['data'=>$grant],201);} public function approve(Request $r,SupportAccessGrant $grant,AuditLogger $audit){$grant->update(['state'=>'approved','approved_by'=>$r->user()->id]);$audit->record($r,'platform.support.access.approved',$grant->tenant_id,$grant);return response()->json(['data'=>$grant->fresh()]);} }
